const e="espagne",l=1,s={habitants:"les Espagnols",adjectif:"espagnol",adjectifF:"espagnole",devise:"Il n'y a pas de crise qu'une bonne sieste ne retarde",medaillon:"ES",chaineInfo:"ES NOTICIAS",hymne:"Vive l'Espagne et ses dix-sept pactes"},n={chambre:"Cortes",chambreLong:"Cortes générales (Congrès des députés et Sénat)",chefGouvernement:"Président du gouvernement",chefEtat:"Roi (rôle protocolaire)",passageForce:{label:"Décret-loi d'urgence",description:"Le gouvernement adopte un texte par décret-loi pour cause d'« extraordinaire et urgente nécessité », puis demande au Congrès de le valider dans les trente jours. Il est très urgent, sauf quand il faut le valider.",news:"Décret-loi sur {loi} : l'urgence est déclarée, le Congrès l'examinera dans trente jours"},censure:{label:"Motion de censure constructive",description:"Pour renverser le gouvernement, l'opposition doit proposer un candidat alternatif et réunir la majorité absolue. La censure espagnole veut un plan B, un plan C et un budget.",news:"Motion de censure constructive : l'opposition a un candidat, mais pas encore de majorité"},dissolution:{label:"Dissolution des Cortes",description:"Le président du gouvernement demande au Roi de dissoudre les Cortes et de convoquer des élections. Il choisit le jour en évitant les fêtes patronales, ce qui est plus difficile qu'on ne croit.",news:"Cortes dissoutes : le Roi signe, les affiches de campagne sont déjà collées"}},t={type:"legislatives",label:"Élections générales",intro:"Trois semaines de campagne en plein été ou en plein hiver, selon la tradition de la coalition, avec des meetings en plein soleil, des débats à rallonge et des promesses sur l'eau, le logement et les autonomies.",adversaires:[{id:"adv-es-1",name:"Álvaro Quintanilla-Reyes",parti:"Parti Populaire National",style:"attaque",punchlines:["Mon adversaire gouverne comme on arrose : un peu partout et trop tard.","Ils ont un pacte avec tout le monde, sauf avec les chiffres.","Je ne promets pas la pluie, je promets des tuyaux."]},{id:"adv-es-2",name:"Marisol Echeverría",parti:"Socialistes Ouvriers Réunis",style:"emotion",punchlines:["Gouverner, c'est écouter dix-sept communautés et trois cafés.","Mon adversaire a les réponses ; moi, j'ai les électeurs.","Les jeunes ne demandent pas la lune, seulement un loyer inférieur à leur salaire."]},{id:"adv-es-3",name:"Joaquín Bellavista",parti:"Gauche Plurielle",style:"chiffres",punchlines:["Les données sont claires : sur le logement, on a promis plus qu'on n'a construit.","Un euro bien dépensé vaut mieux que dix euros bien annoncés.","Mon programme est financé : il suffit de lire la page 214."]}],nuitElectorale:"Dans la nuit électorale, les résultats arrivent par communauté autonome, avec dix-sept chroniqueurs et une calculatrice partagée. Personne n'a la majorité, tout le monde a un accord possible, et le café tient lieu de programme."},a=[{id:"espagne-plan-hydrologique",title:"Plan hydrologique national",domain:"ecologie",description:"Transférer l'eau des bassins excédentaires vers les bassins assoiffés, avec des barrages, des canalisations et de très longs débats sur le tracé. Chaque région juge son eau « inaliénable » et celle des autres « abondante ».",accroche:"L'eau voyagera enfin d'une région à l'autre, en première classe et sans conflit.",effects:{ecologie:3,budget:-5,cohesion:-1,popularite:1},delayed:[{delay:4,effects:{ecologie:2,economie:2},label:"L'eau arrive, les querelles aussi"}],groupStance:{"popular-nacional":.4,"socialistas-obreros":.6,"vox-patria":.3,"plural-izquierda":.2,"republicanos-cat":-.7,"junts-valles":-.5,"ciudadanos-ar":.5},streetAnger:.2},{id:"espagne-financement-autonomies",title:"Nouveau financement des autonomies",domain:"institutions",description:"Réviser la répartition des ressources entre l'État et les communautés autonomes. Chaque communauté obtient « un peu plus que les autres » : mathématiquement délicat, politiquement nécessaire.",accroche:"Chaque autonomie reçoit sa part, et jure que celle des voisines est plus grosse.",effects:{cohesion:3,budget:-4,assemblee:3,popularite:-2},delayed:[{delay:4,effects:{cohesion:1,assemblee:1},label:"Les régions comparent leurs chèques et se disputent le plus gros"}],groupStance:{"popular-nacional":-.6,"socialistas-obreros":.5,"vox-patria":-.8,"plural-izquierda":.5,"republicanos-cat":1,"junts-valles":.9,"ciudadanos-ar":-.2},streetAnger:.1},{id:"espagne-taxe-touristique",title:"Taxe touristique et plafonnement des locations saisonnières",domain:"ecologie",description:"Faire payer les visiteurs et limiter les appartements touristiques dans les centres-villes. Les habitants récupèrent leurs rues ; les loueurs, leur sens du droit de propriété.",accroche:"Les visiteurs paieront un petit supplément pour le plaisir d'avoir été reçus.",effects:{pouvoirAchat:2,ecologie:3,budget:3,economie:-3,popularite:1},delayed:[{delay:4,effects:{pouvoirAchat:2,cohesion:1},label:"Les loyers se détendent, les terrasses un peu moins"}],groupStance:{"popular-nacional":-.4,"socialistas-obreros":.5,"vox-patria":-.5,"plural-izquierda":.9,"republicanos-cat":.7,"junts-valles":.4,"ciudadanos-ar":.2},streetAnger:.3},{id:"espagne-bonus-loyer-jeunes",title:"Bonus loyer pour les jeunes",domain:"logement",description:"Verser une aide au loyer aux moins de trente-cinq ans. Les propriétaires y voient un signal, qu'ils traduisent immédiatement en hausse de prix.",accroche:"Les jeunes toucheront un bonus loyer, au moment d'emménager chez leurs parents.",effects:{pouvoirAchat:4,popularite:3,budget:-4,economie:-1},delayed:[{delay:3,effects:{pouvoirAchat:-1,budget:-1},label:"Les loyers anticipent l'aide et la dépassent"}],groupStance:{"popular-nacional":.1,"socialistas-obreros":.8,"vox-patria":0,"plural-izquierda":.9,"republicanos-cat":.5,"junts-valles":.4,"ciudadanos-ar":.3},streetAnger:.1},{id:"espagne-autoconsommation-solaire",title:"Autoconsommation solaire pour tous",domain:"energie",description:"Simplifier l'installation de panneaux sur les toits et le partage d'électricité entre voisins. Le soleil, déjà actionnaire majoritaire, devrait être ravi.",accroche:"Chaque toit produit son courant, et le voisin du dessous réclame sa part d'ombre.",effects:{ecologie:4,pouvoirAchat:2,economie:2,budget:-3},delayed:[{delay:4,effects:{pouvoirAchat:2,ecologie:2},label:"Les toits produisent, les compteurs hésitent"}],groupStance:{"popular-nacional":.4,"socialistas-obreros":.8,"vox-patria":0,"plural-izquierda":.9,"republicanos-cat":.5,"junts-valles":.7,"ciudadanos-ar":.6},streetAnger:0},{id:"espagne-horaires-rationnels",title:"Réforme des horaires de travail",domain:"travail",description:"Avancer le déjeuner à treize heures et le dîner à vingt et une heures. La sieste obtient le statut de « pause biologique protégée », sous réserve d'un formulaire.",accroche:"Le déjeuner avance d'une heure, le dîner proteste jusqu'à vingt-deux heures.",effects:{popularite:-1,economie:2,cohesion:1,pouvoirAchat:1},delayed:[{delay:3,effects:{economie:2,popularite:1},label:"Les familles dînent avant que les enfants s'endorment"}],groupStance:{"popular-nacional":.3,"socialistas-obreros":.6,"vox-patria":-.4,"plural-izquierda":.7,"republicanos-cat":.2,"junts-valles":.3,"ciudadanos-ar":.9},streetAnger:.2},{id:"espagne-pacte-de-legislature",title:"Pacte de législature entre partis",domain:"institutions",description:"Signer par écrit une feuille de route de coalition, pour que les partenaires ne la découvrent pas dans les journaux. Le document tient en quarante-deux pages et une annexe.",accroche:"Un pacte signé en juin et solide jusqu'à la sieste du mois de juillet.",effects:{assemblee:4,popularite:-2,cohesion:1},delayed:[{delay:4,effects:{assemblee:2},label:"Les partenaires relisent le pacte, chacun avec sa lecture"}],groupStance:{"popular-nacional":-.1,"socialistas-obreros":.8,"vox-patria":-.7,"plural-izquierda":.5,"republicanos-cat":.4,"junts-valles":.3,"ciudadanos-ar":.5},streetAnger:0},{id:"espagne-langues-cooficielles",title:"Usage des langues co-officielles au Parlement",domain:"institutions",description:"Autoriser tous les députés à s'exprimer dans leur langue régionale, avec traduction simultanée. Le budget des écouteurs double, le niveau de compréhension aussi.",accroche:"Chacun parle sa langue, le traducteur surmené réclame désormais une chaise longue.",effects:{cohesion:2,assemblee:2,popularite:-3,budget:-1},delayed:[{delay:3,effects:{cohesion:2,assemblee:1},label:"Les débats durent plus longtemps, mais mieux compris"}],groupStance:{"popular-nacional":-.5,"socialistas-obreros":.6,"vox-patria":-.9,"plural-izquierda":.7,"republicanos-cat":1,"junts-valles":.8,"ciudadanos-ar":0},streetAnger:.1},{id:"espagne-modernisation-irrigation",title:"Modernisation de l'irrigation agricole",domain:"agriculture",description:"Passer à l'irrigation au goutte-à-goutte et réduire les fuites des canaux. Les agriculteurs applaudissent le principe et attendent le détail des subventions.",accroche:"Chaque goutte compte, et la goutte à goutte se vante d'avoir tout compris.",effects:{ecologie:3,economie:2,budget:-4,popularite:1},delayed:[{delay:4,effects:{economie:2,ecologie:1},label:"Les vergers boivent moins, produisent autant"}],groupStance:{"popular-nacional":.6,"socialistas-obreros":.7,"vox-patria":.4,"plural-izquierda":.5,"republicanos-cat":.3,"junts-valles":.2,"ciudadanos-ar":.6},streetAnger:0},{id:"espagne-prevention-incendies",title:"Plan de prévention des incendies de forêt",domain:"ecologie",description:"Débroussailler, former des brigades et surveiller les massifs avant l'été. Les promeneurs sont priés de ne pas considérer une pinède sèche comme un feu de camp.",accroche:"On nettoie les forêts avant l'été, parce que le soleil ne prévient jamais.",effects:{ecologie:3,securite:3,budget:-4,popularite:1},delayed:[{delay:3,effects:{securite:2,ecologie:1},label:"Un été sans grande flamme, c'est déjà un exploit"}],groupStance:{"popular-nacional":.5,"socialistas-obreros":.7,"vox-patria":.3,"plural-izquierda":.5,"republicanos-cat":.4,"junts-valles":.5,"ciudadanos-ar":.7},streetAnger:0}],o=JSON.parse(`[{"id":"espagne-secheresse-historique","title":"Sécheresse historique","category":"climat","description":"Les réservoirs tombent à vingt pour cent et plusieurs villes annoncent des coupures nocturnes. Les golfs maintiennent leurs pelouses, au nom de la tradition et de l'emploi.","weight":6,"minTurn":2,"choices":[{"id":"restrictions","label":"Imposer des restrictions d'eau nationales","description":"Douches courtes, piscines vides, golfs sobres.","effects":{"ecologie":3,"popularite":-4,"economie":-2,"cohesion":1},"delayed":[{"delay":3,"effects":{"ecologie":2},"label":"Les réservoirs remontent de quelques points"}],"news":"Restrictions d'eau : les piscines apprennent le silence"},{"id":"dessalement","label":"Lancer des usines de dessalement","description":"L'eau de mer, enfin utile à autre chose qu'aux vacances.","effects":{"budget":-5,"economie":1,"ecologie":-1,"popularite":2},"delayed":[{"delay":4,"effects":{"economie":2,"cohesion":1},"label":"L'eau coule à nouveau, à un tarif honorable"}],"news":"Dessalement : la mer devient une ressource, avec facture"},{"id":"priere-et-patience","label":"Compter sur la pluie d'automne","description":"Un communiqué d'optimisme atmosphérique.","effects":{"popularite":-3,"ecologie":-2,"economie":-2},"news":"Sécheresse : le gouvernement mise sur les nuages"}]},{"id":"espagne-autonomies-bras-de-fer","title":"Le bras de fer des autonomies","category":"politique","description":"Deux communautés autonomes réclament de nouvelles compétences et menacent de bloquer le budget. Chacune dit vouloir le dialogue, à condition qu'il commence par une concession.","weight":5,"minTurn":3,"conditions":[{"gauge":"assemblee","op":"<","value":52}],"choices":[{"id":"pacte-bilateral","label":"Négocier un pacte bilatéral","description":"Un accord par région, aucun accord pour tout le monde.","effects":{"assemblee":4,"cohesion":-2,"budget":-3},"news":"Pacte bilatéral signé : les autres communautés demandent le même"},{"id":"commission-mixte","label":"Réunir une commission mixte État-régions","description":"Une salle, un café, un procès-verbal.","effects":{"cohesion":2,"assemblee":1,"popularite":-1},"delayed":[{"delay":3,"effects":{"cohesion":1,"assemblee":1},"label":"Un calendrier est enfin adopté"}],"news":"Commission mixte réunie : le café est excellent, les résultats attendus"},{"id":"fermete","label":"Rappeler la Constitution","description":"Un discours sobre, un article rappelé et un silence.","effects":{"cohesion":-4,"assemblee":-3,"popularite":1},"news":"Fermeté constitutionnelle : le Parlement résonne de discours enflammés"}]},{"id":"espagne-tourisme-de-masse","title":"Quand les visiteurs dépassent les habitants","category":"economie","description":"Une ville côtière compte désormais plus de touristes que d'habitants le mois d'août. Les riverains manifestent avec des pistolets à eau, geste symbolique et efficacement rafraîchissant.","weight":5,"minTurn":2,"choices":[{"id":"quota-visiteurs","label":"Instaurer un quota de visiteurs","description":"Un nombre maximal d'arrivées par jour, avec liste d'attente.","effects":{"ecologie":3,"cohesion":2,"economie":-3,"popularite":1},"delayed":[{"delay":3,"effects":{"cohesion":2,"ecologie":1},"label":"Les riverains retrouvent leur trottoir"}],"news":"Quota de visiteurs : la plage a désormais un videur"},{"id":"tourisme-premium","label":"Viser un tourisme plus haut de gamme","description":"Moins de monde, plus de dépenses.","effects":{"economie":2,"pouvoirAchat":-2,"cohesion":-2,"budget":2},"news":"Tourisme haut de gamme : les chaises longues deviennent des investissements"},{"id":"laisser-saison","label":"Laisser faire la saison","description":"Août est court, la facture de la politique plus longue.","effects":{"economie":3,"ecologie":-3,"cohesion":-3,"popularite":-2},"news":"Saison record : les caisses sourient, les riverains moins"}]},{"id":"espagne-budget-proroge","title":"Le budget prorogé","category":"politique","description":"Faute de majorité, le budget n'est pas voté et celui de l'an dernier est prorogé, avec une certaine mélancolie. Les ministres promettent de faire preuve de sobriété dans les dépenses non prévues.","weight":5,"minTurn":3,"conditions":[{"gauge":"assemblee","op":"<","value":48}],"choices":[{"id":"negocier-partenaires","label":"Négocier avec les petits groupes","description":"Une compétence par vote, deux crédits par abstention.","effects":{"assemblee":4,"budget":-4,"cohesion":-1},"news":"Négociations budgétaires : chaque voix a son prix et sa région"},{"id":"motion-confiance","label":"Poser la question de confiance","description":"Demander au Congrès de choisir entre le budget et le vide.","effects":{"assemblee":3,"popularite":-3,"international":-1},"news":"Question de confiance : le gouvernement mise tout sur le mercredi"},{"id":"gouverner-par-decret","label":"Gouverner par décrets-lois","description":"Faire sans le vote, avec une signature.","effects":{"assemblee":-4,"budget":2,"popularite":-2},"news":"Décrets-lois en rafale : le Congrès réclame un débat"}]},{"id":"espagne-goutte-froide","title":"Goutte froide sur le littoral","category":"climat","description":"Un épisode de goutte froide déverse en une nuit la pluie d'un trimestre. Des ramblas deviennent des rivières, des garages des piscines, et les prévisionnistes ont l'air résignés.","weight":4,"minTurn":2,"choices":[{"id":"aide-sinistres","label":"Verser une aide immédiate aux sinistrés","description":"Un virement avant les premiers nettoyages.","effects":{"budget":-4,"popularite":3,"cohesion":2},"news":"Goutte froide : une aide d'urgence est annoncée avant l'inventaire"},{"id":"plan-ramblas","label":"Lancer un plan de drainage urbain","description":"Réaménager les lits de rivière et les parkings.","effects":{"budget":-5,"securite":3,"ecologie":2},"delayed":[{"delay":4,"effects":{"securite":2,"cohesion":1},"label":"L'orage suivant passe presque inaperçu"}],"news":"Plan de drainage : les ramblas retrouvent leur rôle"},{"id":"responsabiliser","label":"Renvoyer la gestion aux communautés autonomes","description":"Chacun gère ses ruisseaux.","effects":{"budget":2,"cohesion":-3,"popularite":-3},"news":"Goutte froide : l'État renvoie la gestion aux régions, qui renvoient à l'État"}]},{"id":"espagne-tracteurs-aux-cortes","title":"Tracteurs devant les Cortes","category":"agriculture","description":"Des centaines de tracteurs défilent devant les Cortes pour dénoncer des prix trop bas, des importations trop libres et des formulaires trop longs. La circulation madrilène, elle, juge la manifestation « conforme à ses habitudes ».","weight":4,"minTurn":3,"conditions":[{"gauge":"pouvoirAchat","op":"<","value":52}],"choices":[{"id":"aides-agricoles","label":"Débloquer un paquet d'aides","description":"Des subventions, des garanties de prix et un joli communiqué.","effects":{"budget":-5,"popularite":2,"cohesion":2,"economie":1},"delayed":[{"delay":3,"effects":{"cohesion":1},"label":"Les prix sont rassurés, pour une saison"}],"news":"Paquet d'aides agricoles : les tracteurs rentrent à la ferme"},{"id":"clause-miroir","label":"Imposer des normes équivalentes aux importations","description":"Exiger des autres ce qu'on exige des siens.","effects":{"international":-2,"economie":1,"popularite":2},"news":"Clause miroir : l'agriculture espagnole veut que l'étranger respecte les mêmes règles"},{"id":"dialogue-sectoriel","label":"Ouvrir un dialogue sectoriel","description":"Des réunions, des tableaux et du café fort.","effects":{"popularite":-2,"cohesion":1},"news":"Dialogue sectoriel ouvert : les tracteurs restent garés devant"}]},{"id":"espagne-canicule-et-incendies","title":"Canicule et incendies","category":"climat","description":"Quarante-quatre degrés à l'ombre, des forêts sèches et des étincelles de tout genre. Des brigades de pompiers volontaires arrivent à pied, en voiture et parfois à dos de mulet.","weight":4,"minTurn":2,"conditions":[{"gauge":"ecologie","op":"<","value":55}],"choices":[{"id":"moyens-aeriens","label":"Mobiliser tous les moyens aériens","description":"Bombardiers d'eau et hélicoptères, sans compter.","effects":{"budget":-4,"securite":3,"popularite":2},"news":"Moyens aériens mobilisés : l'été vire à l'opération militaire"},{"id":"evacuations-preventives","label":"Ordonner des évacuations préventives","description":"Éloigner les habitants avant que le feu ne se décide.","effects":{"securite":3,"cohesion":-1,"popularite":-1,"budget":-2},"news":"Évacuations préventives : les villageois quittent leurs maisons avec leur meilleur jambon"},{"id":"plan-ecologique","label":"Annoncer un grand plan de reboisement","description":"Planter plus de feuillus, moins de résineux.","effects":{"ecologie":3,"budget":-3,"popularite":1},"delayed":[{"delay":4,"effects":{"ecologie":2},"label":"Les forêts reverdissent, doucement"}],"news":"Plan de reboisement annoncé : les pins se demandent s'il s'agit d'eux"}]},{"id":"espagne-victoire-championnat","title":"Victoire de l'équipe nationale","category":"politique","kind":"evenement","description":"L'équipe nationale remporte un titre continental dans la nuit. Les places de villages débordent, les bars manquent de verres et le gouvernement vérifie que personne n'a organisé de contre-manifestation.","weight":3,"conditions":[{"gauge":"popularite","op":">","value":38}],"choices":[{"id":"balcon-champions","label":"Féliciter les joueurs depuis le balcon du palais","description":"Une cérémonie, un drapeau et un discours de huit secondes.","effects":{"popularite":3,"cohesion":3,"budget":-1},"news":"Le président du gouvernement salue les champions depuis un balcon qui n'a pas l'habitude"},{"id":"jour-ferie","label":"Décréter un jour férié","description":"Une fête, une nuit et un lendemain de fête.","effects":{"popularite":4,"economie":-2,"cohesion":2},"news":"Jour férié : l'économie dort jusqu'à midi"},{"id":"communique-sobre","label":"Se contenter d'un communiqué","description":"Le sport, c'est le sport.","effects":{"popularite":1,"cohesion":1},"news":"Le gouvernement félicite l'équipe d'une phrase correctement ponctuée"}]}]`),i=[{id:"espagne-eau-retrouvee",title:"Rassurer les réservoirs",brief:"Gagnez 4 points d'écologie : la sécheresse n'a pas de parti, mais elle a un calendrier.",objective:{type:"gaugeGain",gauge:"ecologie",value:4},reward:{ecologie:2,popularite:1},news:"Écologie : les réservoirs remontent, la presse se calme"},{id:"espagne-pacte-solide",title:"Garder le pacte de coalition intact",brief:"Un indice d'assemblée à 52 : suffisant pour vérifier que le pacte tient sans que personne ne le relise.",objective:{type:"gaugeAtLeast",gauge:"assemblee",value:52},reward:{assemblee:2,popularite:1},news:"Pacte de coalition : toujours en vigueur, mystérieusement"},{id:"espagne-autonomies-satisfaites",title:"Apaiser les autonomies",brief:"Tenez la cohésion à 52 : dix-sept communautés, dix-sept demandes, une seule patience.",objective:{type:"gaugeAtLeast",gauge:"cohesion",value:52},reward:{cohesion:2,assemblee:1},news:"Autonomies : chaque communauté se déclare à peu près satisfaite, ce qui est un exploit"},{id:"espagne-sans-voyant-rouge",title:"Un trimestre sans voyant rouge",brief:"Aucune jauge dans le rouge : une sieste politique, enfin méritée.",objective:{type:"noRedGauge"},reward:{popularite:1,budget:1},news:"Aucune jauge dans le rouge : le gouvernement respire, discrètement"}],r=JSON.parse('{"medias":["Diario del Patio","Radio Meseta","Canal Sol 24","La Gaceta de la Siesta","El Observador Autonómico"],"journalistes":[{"id":"espagne-j-inmaculada","name":"Inmaculada Torrecilla-Vega","media":"Diario del Patio","style":"tenace : relance jusqu’à la fermeture du bar","genre":"f"},{"id":"espagne-j-rodrigo","name":"Rodrigo Montalbán","media":"Radio Meseta","style":"provocateur : pose la question piège pendant la sieste de l’attaché de presse"},{"id":"espagne-j-pilar","name":"Pilar Zumárraga","media":"Canal Sol 24","style":"alarmiste : tout est une alerte rouge, surtout le bandeau défilant"},{"id":"espagne-j-ignacio","name":"Ignacio Valdecasas","media":"El Observador Autonómico","style":"économiste : un tableau dans chaque question, un abaque dans chaque poche","genre":"m"},{"id":"espagne-j-consuelo","name":"Consuelo Benavides","media":"La Gaceta de la Siesta","style":"complaisante : demande si la sieste d’hier était bonne","genre":"f"},{"id":"espagne-j-tomas","name":"Tomás Albarracín","media":"Radio Meseta","style":"chroniqueur sportif : ramène tout au football, même le budget"},{"id":"espagne-j-lucia","name":"Lucía Ormaechea","media":"Canal Sol 24","style":"enquêtrice : arrive avec un dossier, des pièces jointes et un café"}],"questions":[{"id":"espagne-q-sondage-rue","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":40},"text":"Chef du gouvernement, vos sondages sont si bas qu’on les cherche désormais avec une lampe de poche. Le palais de la Moncloa Nova a-t-il perdu le contact avec la rue ?","answers":[{"tone":"franche","label":"Le contact n’est pas perdu, il est tendu. J’irai davantage dans les marchés, quitte à y entendre mon titre suivi d’adjectifs.","effects":{"popularite":4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les étals voisins applaudissent poliment"}],"news":"Le chef du gouvernement promet de descendre dans la rue, parapluie en main"},{"tone":"langue-de-bois","label":"La rue est un concept riche. Nous l’écoutons chaque jour, par les canaux appropriés et dans le respect des horaires de chacun.","effects":{"popularite":2,"assemblee":-2},"news":"Le chef du gouvernement assure écouter la rue « par les canaux appropriés »"},{"tone":"offensive","label":"La rue, c’est surtout un sondage commandé par ceux qui n’y mettent jamais les pieds. Mon bilan se juge aux urnes, pas aux terrasses.","effects":{"popularite":5,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Les terrasses se vengent dans les commentaires"}],"news":"Le chef du gouvernement renvoie les sondages à leurs terrasses"}]},{"id":"espagne-q-chomage-reprise","theme":"economie","condition":{"gauge":"economie","op":"<","value":45},"text":"Le chômage reste parmi les plus hauts du continent et vos ministres parlent de « reprise » avec un enthousiasme de présentateurs météo. Où sont les emplois, chef du gouvernement ?","answers":[{"tone":"franche","label":"Les emplois sont en retard, comme souvent. Nous financerons la formation et l’embauche des jeunes, mais les résultats demanderont des années.","effects":{"economie":3,"budget":-4},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les premières embauches arrivent, avec contrat"}],"news":"Le chef du gouvernement admet que les emplois sont « en retard »"},{"tone":"langue-de-bois","label":"Le marché du travail connaît une transition dynamique vers un équilibre prometteur de perspectives structurantes pour tous les acteurs.","effects":{"economie":2,"popularite":-2},"news":"Le chef du gouvernement évoque « une transition dynamique » du marché du travail"},{"tone":"offensive","label":"Les emplois sont dans les entreprises qui investissent, pas sur les plateaux de télévision. Que l’opposition cesse de les décourager !","effects":{"economie":4,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Les chômeurs trouvent la formule vexante"}],"news":"Le chef du gouvernement accuse l’opposition de « décourager les emplois »"}]},{"id":"espagne-q-caisses-vides","theme":"budget","condition":{"gauge":"budget","op":"<","value":35},"text":"Les caisses de l’État ressemblent au frigo d’une colocation en fin de mois : trois olives et beaucoup d’espoir. Allez-vous augmenter les impôts ou vendre les meubles du palais ?","answers":[{"tone":"franche","label":"Il faudra des recettes nouvelles, et je préfère le dire avant l’élection plutôt qu’après. Nous taxerons les rentes avant les salaires.","effects":{"budget":5,"popularite":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les groupes demandent un peu de temps et beaucoup de garanties"}],"news":"Le chef du gouvernement annonce de nouvelles recettes, avant l’élection, fait rare"},{"tone":"langue-de-bois","label":"La situation budgétaire est sous contrôle, à condition de contrôler ce qu’on entend par situation, budgétaire et contrôle.","effects":{"budget":2,"economie":-2},"news":"Le chef du gouvernement assure que le budget est « sous contrôle »"},{"tone":"offensive","label":"Les meubles du palais sont déjà vendus, et l’opposition n’a pas remarqué. Elle a laissé les caisses vides, elle peut bien en parler tout bas.","effects":{"popularite":4,"assemblee":-3,"international":-2},"delayed":[{"delay":3,"effects":{"budget":-2},"label":"Le palais cherche des chaises en location"}],"news":"Le chef du gouvernement ironise sur les « meubles du palais déjà vendus »"}]},{"id":"espagne-q-loyers-jeunes","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":40},"text":"Un jeune actif consacre la moitié de son salaire à un studio dont le lit sert aussi de bureau, de table et de salon. Quand verra-t-on un logement abordable pour sa génération ?","answers":[{"tone":"franche","label":"Pas demain, je ne vais pas vous mentir. Nous construirons, nous plafonnerons les loyers là où c’est nécessaire, et nous irons moins vite que vos attentes.","effects":{"pouvoirAchat":4,"economie":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les jeunes comptent les mois avec un nouvel espoir"}],"news":"Le chef du gouvernement promet du logement, mais « pas demain »"},{"tone":"langue-de-bois","label":"Le logement est une priorité transversale, au croisement de multiples compétences, autonomes comme nationales, qui travaillent ensemble de manière partagée.","effects":{"pouvoirAchat":2,"assemblee":-2},"news":"Logement : le chef du gouvernement évoque une « priorité transversale »"},{"tone":"offensive","label":"Si les loyers sont chers, c’est parce que certains propriétaires ont oublié l’intérêt général. Ils vont le réapprendre, par décret.","effects":{"pouvoirAchat":5,"economie":-3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les promoteurs réfléchissent à construire ailleurs"}],"news":"Le chef du gouvernement menace les loyers excessifs d’un décret"}]},{"id":"espagne-q-cambriolages-littoral","theme":"securite","condition":{"gauge":"securite","op":"<","value":40},"text":"Après une série de cambriolages sur la côte, certains maires veulent engager des vigiles en tongs. L’État a-t-il perdu la maîtrise de la sécurité hors saison ?","answers":[{"tone":"franche","label":"Les effectifs manquent là où l’on en a besoin, et c’est ma responsabilité. Nous renforcerons les patrouilles, au prix de coupes ailleurs.","effects":{"securite":4,"budget":-3},"delayed":[{"delay":3,"effects":{"securite":2},"label":"Les patrouilles arrivent, toujours avant le week-end"}],"news":"Le chef du gouvernement reconnaît un manque de patrouilles sur le littoral"},{"tone":"langue-de-bois","label":"La sécurité est l’affaire de tous, des mairies aux préfectures, et il serait injuste de désigner un responsable plutôt qu’un autre.","effects":{"securite":2,"popularite":-2},"news":"Cambriolages : le chef du gouvernement répartit la responsabilité entre tous"},{"tone":"offensive","label":"Les maires qui s’inquiètent devraient d’abord vérifier qu’ils ont fermé leurs propres fenêtres. L’État fait son travail, qu’ils fassent le leur.","effects":{"securite":5,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les maires organisent une conférence de presse commune"}],"news":"Le chef du gouvernement renvoie les maires à leurs fenêtres"}]},{"id":"espagne-q-autonomies-ruban","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":35},"text":"Chaque communauté autonome réclame davantage de compétences, et certaines voudraient pouvoir dire non à toutes les autres. La cohésion du pays tient-elle encore avec du ruban adhésif ?","answers":[{"tone":"franche","label":"Oui, par moments, et le ruban s’appelle le dialogue. Je vais me réunir avec chaque président régional, sans promettre ce que je ne peux pas donner.","effects":{"cohesion":4,"popularite":-3},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Les régionalistes saluent l’écoute, pas encore l’échéancier"}],"news":"Le chef du gouvernement reconnaît un pays tenu par « du ruban adhésif »"},{"tone":"langue-de-bois","label":"L’Espagne est un pays diversifié, riche de ses différences et fort de ses convergences, dans le respect du cadre constitutionnel et de ses évolutions.","effects":{"cohesion":2,"popularite":-2},"news":"Le chef du gouvernement salue un pays « riche de ses différences »"},{"tone":"offensive","label":"Un pays n’est pas un buffet où chacun choisit ses plats sans payer l’addition. La solidarité n’est pas une option, c’est une obligation.","effects":{"popularite":4,"cohesion":-4,"assemblee":-3},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les groupes régionalistes sortent leurs agendas"}],"news":"Le chef du gouvernement : « Un pays n’est pas un buffet »"}]},{"id":"espagne-q-rivieres-golfs","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":40},"text":"Les rivières se réduisent, mais les golfs restent d’un vert éclatant. Comment justifier cette curieuse hiérarchie dans la distribution de l’eau ?","answers":[{"tone":"franche","label":"Vous avez raison, la hiérarchie est mauvaise. Les usages agricoles et domestiques passeront avant les loisirs, même si des investisseurs grinceront.","effects":{"ecologie":4,"economie":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les agriculteurs saluent la priorité, les golfeurs soupirent"}],"news":"Le chef du gouvernement remet les golfs derrière les robinets"},{"tone":"langue-de-bois","label":"L’eau est une ressource précieuse que nous gérerons de manière équilibrée, durable et concertée, dans toutes ses dimensions et tous ses usages.","effects":{"ecologie":2,"popularite":-2},"news":"Le chef du gouvernement promet une gestion « équilibrée » de l’eau"},{"tone":"offensive","label":"Les golfs font vivre des villages entiers. Ceux qui les attaquent préfèrent la poussière aux emplois, et je ne partage pas ce goût.","effects":{"economie":4,"ecologie":-4,"popularite":-2},"delayed":[{"delay":2,"effects":{"ecologie":-2},"label":"Les nappes phréatiques demandent à être consultées"}],"news":"Le chef du gouvernement défend les golfs contre « la poussière »"}]},{"id":"espagne-q-voix-bruxelles","theme":"international","condition":{"gauge":"international","op":"<","value":40},"text":"Vos partenaires européens adorent l’Espagne, surtout en vacances. Pourquoi votre voix pèse-t-elle à Bruxelles moins que votre paella au restaurant ?","answers":[{"tone":"franche","label":"Parce que nous arrivons souvent sans position commune entre régions et partis. Je vais d’abord rassembler à la maison pour parler plus fort dehors.","effects":{"international":4,"popularite":-2},"delayed":[{"delay":3,"effects":{"international":2},"label":"Les capitales se souviennent soudain de notre numéro"}],"news":"Le chef du gouvernement veut d’abord « rassembler à la maison »"},{"tone":"langue-de-bois","label":"L’Espagne est un partenaire fiable, engagé, constructif et attaché à une Europe forte, unie, ambitieuse et, naturellement, solidaire.","effects":{"international":2,"popularite":-2},"news":"Le chef du gouvernement décrit l’Espagne comme un « partenaire fiable »"},{"tone":"offensive","label":"Ma paella pèse plus parce qu’elle est meilleure que certains discours. Si Bruxelles veut notre voix, elle devra aussi verser sa part des fonds.","effects":{"economie":3,"international":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Une capitale demande poliment qu’on baisse d’un ton"}],"news":"Le chef du gouvernement réclame sa part des fonds européens, paella à l’appui"}]},{"id":"espagne-q-sept-groupes","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":35},"text":"Il vous faut le soutien de sept groupes, dont deux régionalistes qui votent un budget contre une compétence. Combien de temps tiendra cette majorité en dentelle ?","answers":[{"tone":"franche","label":"Je ne le sais pas, et personne ne peut vous le dire honnêtement. Je négocierai loi par loi, et je dirai à chacun ce qu’il obtient.","effects":{"assemblee":4,"popularite":-2},"delayed":[{"delay":2,"effects":{"budget":-2},"label":"Les groupes régionalistes ouvrent le carnet de commandes"}],"news":"Le chef du gouvernement : la majorité tiendra « loi par loi »"},{"tone":"langue-de-bois","label":"Cette majorité repose sur un dialogue constant, un respect mutuel et une responsabilité partagée devant les Espagnols et leurs territoires.","effects":{"assemblee":2,"popularite":-2},"news":"Le chef du gouvernement vante un « dialogue constant » au Congrès"},{"tone":"offensive","label":"Cette majorité tient mieux que l’opposition, qui n’a même pas réussi à s’entendre sur la couleur de sa cravate. Qu’elle commence par là.","effects":{"popularite":4,"assemblee":-4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Un groupe allié oublie de répondre au téléphone"}],"news":"Le chef du gouvernement raille les cravates de l’opposition"}]},{"id":"espagne-q-grace-sieste","theme":"popularite","condition":{"gauge":"popularite","op":">","value":65},"text":"Votre popularité est élevée, ce qui est presque suspect dans ce pays. Craignez-vous que l’état de grâce ne dure que le temps d’une sieste ?","answers":[{"tone":"franche","label":"C’est possible, et je m’y prépare. Je préfère dépenser cette confiance sur des réformes difficiles plutôt que de la ranger dans un tiroir.","effects":{"assemblee":3,"popularite":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les réformes avancent, les sourires aussi, un peu moins"}],"news":"Le chef du gouvernement veut « dépenser sa popularité » en réformes"},{"tone":"langue-de-bois","label":"La confiance se construit chaque jour, avec humilité, et nous restons concentrés sur les priorités des Espagnols, sans regarder le calendrier.","effects":{"popularite":2,"economie":-2},"news":"Le chef du gouvernement reste « humble » face à des sondages favorables"},{"tone":"offensive","label":"Mon état de grâce ne dort pas : il gouverne. Ceux qui rêvent de le voir finir peuvent continuer à rêver, c’est gratuit.","effects":{"popularite":3,"cohesion":-3,"international":-2},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Les commentateurs vérifient l’état de la sieste"}],"news":"Le chef du gouvernement : « Mon état de grâce ne dort pas »"}]},{"id":"espagne-q-serveur-proprietaire","theme":"economie","condition":{"gauge":"economie","op":">","value":65},"text":"L’économie va bien, les terrasses sont pleines, les touristes aussi. Mais qui profite vraiment de la croissance : le serveur, ou le propriétaire de l’appartement au-dessus ?","answers":[{"tone":"franche","label":"Trop souvent le deuxième, c’est vrai. Nous augmenterons le salaire minimum et taxerons davantage la rente, quitte à fâcher quelques portefeuilles.","effects":{"pouvoirAchat":4,"economie":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les serveurs repartent avec des pourboires et un sourire"}],"news":"Le chef du gouvernement veut que la croissance profite aussi au serveur"},{"tone":"langue-de-bois","label":"La croissance est partagée par l’ensemble des acteurs économiques, dans une logique de gagnant-gagnant que personne ne peut raisonnablement contester.","effects":{"economie":2,"cohesion":-2},"news":"Le chef du gouvernement assure que la croissance est « partagée »"},{"tone":"offensive","label":"Ceux qui critiquent la croissance feraient bien de goûter la récession, elle est moins bonne que notre jambon. Merci à ceux qui travaillent.","effects":{"economie":4,"popularite":3,"cohesion":-4},"delayed":[{"delay":2,"effects":{"pouvoirAchat":-2},"label":"Les loyers lisent les statistiques et prennent des notes"}],"news":"Le chef du gouvernement : mieux vaut la croissance que la « récession au jambon »"}]},{"id":"espagne-q-voix-amerique","theme":"international","condition":{"gauge":"international","op":">","value":65},"text":"L’Espagne est écoutée à l’étranger, notamment en Amérique latine. Allez-vous profiter de ce crédit pour donner des leçons, ou seulement des conseils ?","answers":[{"tone":"franche","label":"Des conseils, quand on nous les demande, et des écoutes beaucoup plus souvent. Notre histoire commune impose de la modestie, pas de la nostalgie.","effects":{"international":4,"popularite":-2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"De nouveaux accords commerciaux arrivent en espagnol"}],"news":"Le chef du gouvernement : « des conseils, et surtout de l’écoute »"},{"tone":"langue-de-bois","label":"Nos liens historiques, culturels et linguistiques constituent une chance partagée que nous entendons faire fructifier dans un esprit de coopération.","effects":{"international":2,"economie":-2},"news":"Le chef du gouvernement célèbre des liens « historiques et culturels »"},{"tone":"offensive","label":"Nous donnerons des leçons à qui en a besoin, puisque nous avons l’expérience de quelques transitions. Le monde nous écoute, profitons-en !","effects":{"popularite":4,"international":-4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Trois ambassadeurs sont convoqués pour des raisons de politesse"}],"news":"Le chef du gouvernement se dit prêt à « donner des leçons » à l’étranger"}]},{"id":"espagne-q-soleil-facture","theme":"ecologie","condition":{"gauge":"ecologie","op":">","value":65},"text":"Le solaire inonde les toits et les champs. Ne craignez-vous pas que l’on finisse par facturer le soleil, comme le reste ?","answers":[{"tone":"franche","label":"Le soleil restera gratuit ; les réseaux pour l’acheminer, non. Nous protégerons l’autoconsommation, mais les gros producteurs paieront leur part.","effects":{"ecologie":4,"economie":-3},"delayed":[{"delay":3,"effects":{"pouvoirAchat":2},"label":"Les factures baissent, les panneaux sourient"}],"news":"Le chef du gouvernement jure que « le soleil restera gratuit »"},{"tone":"langue-de-bois","label":"La transition énergétique est une opportunité majeure qui exige un cadre prévisible, stable, équilibré et favorable à l’investissement responsable.","effects":{"ecologie":2,"international":-2},"news":"Énergie : le chef du gouvernement réclame un « cadre prévisible »"},{"tone":"offensive","label":"Si les grandes compagnies veulent facturer le soleil, elles trouveront un gouvernement qui facture leurs bénéfices. Le ciel est à tout le monde.","effects":{"popularite":4,"economie":-4,"international":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les investisseurs étudient d’autres latitudes"}],"news":"Le chef du gouvernement : « Le ciel est à tout le monde »"}]},{"id":"espagne-q-huile-olive","theme":"pouvoirAchat","text":"Le prix de l’huile d’olive a doublé : dans bien des foyers, elle se range désormais avec les bijoux. Que faites-vous pour les tartines des Espagnols ?","answers":[{"tone":"franche","label":"Je ne peux pas faire pleuvoir sur les oliviers. Je peux alléger la TVA sur les produits de base et aider les producteurs frappés par la sécheresse.","effects":{"pouvoirAchat":4,"budget":-4},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"La tartine retrouve peu à peu son éclat doré"}],"news":"Le chef du gouvernement allège la TVA pour sauver la tartine"},{"tone":"langue-de-bois","label":"Nous suivons attentivement l’évolution des prix des produits alimentaires essentiels et resterons vigilants à toutes les étapes de la filière.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"Huile d’olive : le chef du gouvernement reste « vigilant à chaque étape »"},{"tone":"offensive","label":"Si des intermédiaires s’enrichissent sur le dos de nos tartines, ils trouveront les inspecteurs avant l’aube. L’huile n’est pas un placement.","effects":{"pouvoirAchat":4,"economie":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"La filière se plaint d’être traitée en suspecte"}],"news":"Le chef du gouvernement lance les inspecteurs contre les « spéculateurs d’huile »"}]},{"id":"espagne-q-cheques-regions","theme":"budget","text":"Les communautés autonomes se plaignent de recevoir moins que leurs voisines, qui se plaignent de recevoir moins qu’elles. Le financement est-il équitable, ou seulement bien dissimulé ?","answers":[{"tone":"franche","label":"Il est trop opaque, je l’admets. Je publierai les chiffres région par région, même si cela déclenchera vingt-quatre heures de tempête.","effects":{"cohesion":4,"assemblee":-3},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les calculatrices chauffent dans dix-sept communautés"}],"news":"Le chef du gouvernement va publier les chèques, région par région"},{"tone":"langue-de-bois","label":"Le modèle de financement est le fruit d’un équilibre délicat entre solidarité, corresponsabilité et autonomie, qui mérite d’être préservé.","effects":{"budget":2,"cohesion":-2},"news":"Financement : le chef du gouvernement vante un « équilibre délicat »"},{"tone":"offensive","label":"Ceux qui crient à l’injustice sont souvent ceux qui reçoivent le plus. Je ne négocierai pas sous la pression d’un communiqué de presse.","effects":{"budget":4,"popularite":2,"cohesion":-5},"delayed":[{"delay":3,"effects":{"assemblee":-3},"label":"Un groupe régionaliste suspend les négociations d’un café"}],"news":"Le chef du gouvernement refuse de négocier « sous la pression d’un communiqué »"}]},{"id":"espagne-q-emplois-saisonniers","theme":"economie","text":"Le tourisme fait vivre des millions de personnes, mais les emplois sont saisonniers et peu payés. Comment bâtir une économie qui ne dépende pas du soleil ?","answers":[{"tone":"franche","label":"En investissant dans ce qui ne bronze pas : l’industrie, la recherche, le numérique. Cela coûtera cher et ne se verra pas avant plusieurs étés.","effects":{"economie":4,"budget":-4},"delayed":[{"delay":4,"effects":{"economie":3},"label":"Les premières usines sortent de terre, sans parasol"}],"news":"Le chef du gouvernement veut une économie « qui ne bronze pas »"},{"tone":"langue-de-bois","label":"Le tourisme reste un secteur stratégique que nous accompagnons vers une montée en gamme, tout en diversifiant de façon progressive notre modèle productif.","effects":{"economie":2,"pouvoirAchat":-2},"news":"Le chef du gouvernement promet une « montée en gamme » du tourisme"},{"tone":"offensive","label":"Le soleil est notre pétrole et nous n’avons pas à nous en excuser. Ceux qui méprisent le tourisme n’ont jamais servi cent couverts en août.","effects":{"economie":3,"popularite":3,"ecologie":-4},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Les habitants du centre se sentent un peu moins accueillants"}],"news":"Le chef du gouvernement : « Le soleil est notre pétrole »"}]},{"id":"espagne-q-secheresse-camions","theme":"crise","crisisId":"espagne-secheresse-historique","text":"Les réservoirs sont à un tiers et certaines communes reçoivent leur eau par camion-citerne. Qui doit payer, qui doit boire, et qui doit arroser le golf ?","answers":[{"tone":"franche","label":"Boire passe avant tout. Nous imposerons des restrictions équitables, pour les particuliers comme pour les grands consommateurs, et nous livrerons les communes.","effects":{"ecologie":3,"popularite":2,"economie":-4},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les camions-citernes arrivent à l’heure, un exploit"}],"news":"Sécheresse : le chef du gouvernement fait passer la soif avant le golf"},{"tone":"langue-de-bois","label":"Les ressources hydriques font l’objet d’un suivi permanent et d’une coordination étroite entre bassins, communautés et opérateurs concernés.","effects":{"ecologie":2,"popularite":-2},"news":"Sécheresse : le chef du gouvernement évoque une « coordination étroite »"},{"tone":"offensive","label":"Il y a assez d’eau pour ceux qui travaillent et pas pour ceux qui polémiquent. Que chaque région nettoie ses canalisations avant d’accuser la voisine.","effects":{"popularite":3,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Les présidents régionaux se plaignent… dans des communiqués séparés"}],"news":"Le chef du gouvernement renvoie chaque région à ses canalisations"}]},{"id":"espagne-q-bras-de-fer-pacte","theme":"crise","crisisId":"espagne-autonomies-bras-de-fer","text":"Le bras de fer avec les communautés autonomes dure. Votre solution est-elle un pacte, une négociation, ou une réunion de plus qui s’achèvera à deux heures du matin ?","answers":[{"tone":"franche","label":"Les trois, probablement. Je mettrai tout le monde autour de la table, sans exclure personne, et nous resterons jusqu’à ce que les chaises soient inconfortables.","effects":{"cohesion":4,"assemblee":2,"popularite":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"À deux heures, le café est signé avant le texte"}],"news":"Le chef du gouvernement convoque tout le monde autour de la table, et des chaises dures"},{"tone":"langue-de-bois","label":"Nous poursuivons un dialogue ouvert, sincère et exigeant, dans un climat respectueux des institutions et de la diversité territoriale.","effects":{"cohesion":2,"assemblee":-2},"news":"Autonomies : le chef du gouvernement poursuit un « dialogue exigeant »"},{"tone":"offensive","label":"Je ne céderai pas au chantage budgétaire. La loi vaut pour tous, de la Galice aux Canaries, et on ne marchande pas l’égalité.","effects":{"popularite":4,"cohesion":-5,"assemblee":-3},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Deux groupes régionalistes quittent la salle de réunion"}],"news":"Le chef du gouvernement refuse le « chantage budgétaire » des régions"}]},{"id":"espagne-q-tourisme-valises","theme":"crise","crisisId":"espagne-tourisme-de-masse","text":"Les habitants des centres-villes ne trouvent plus ni boulangerie ni voisins, seulement des valises à roulettes. Allez-vous fermer la porte aux visiteurs ?","answers":[{"tone":"franche","label":"Non, mais je fermerai certaines fenêtres : plafonnement des locations touristiques et une taxe qui servira à loger les habitants. Les visiteurs sont les bienvenus, pas tous en même temps.","effects":{"cohesion":4,"economie":-3},"delayed":[{"delay":3,"effects":{"pouvoirAchat":2},"label":"Les boulangeries rouvrent, les valises s’adaptent"}],"news":"Le chef du gouvernement plafonne les locations touristiques et ouvre une taxe"},{"tone":"langue-de-bois","label":"Nous voulons un tourisme durable, qualitatif et respectueux des territoires, en concertation avec tous les acteurs locaux concernés.","effects":{"cohesion":2,"economie":-2},"news":"Le chef du gouvernement promet un tourisme « durable et qualitatif »"},{"tone":"offensive","label":"Les visiteurs paient nos hôpitaux et nos routes. Que ceux qui les trouvent trop nombreux essaient donc de les remplacer par des moutons.","effects":{"economie":4,"popularite":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Des habitants répondent en brandissant des valises"}],"news":"Le chef du gouvernement défend les visiteurs contre les « moutons »"}]},{"id":"espagne-q-budget-proroge-hier","theme":"crise","crisisId":"espagne-budget-proroge","text":"Le budget est prorogé pour la deuxième année : l’État dépense avec les chiffres d’hier pour les problèmes de demain. Quand aurons-nous un budget neuf ?","answers":[{"tone":"franche","label":"Dès que j’aurai une majorité sérieuse, et je ne l’aurai pas en achetant des voix. Je préfère un budget tardif mais honnête à un budget rapide et truqué.","effects":{"budget":3,"assemblee":2,"popularite":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les ministères apprennent à compter autrement"}],"news":"Le chef du gouvernement préfère un budget « tardif mais honnête »"},{"tone":"langue-de-bois","label":"La prorogation garantit la continuité de l’action publique. Nous travaillons à une solution adaptée au contexte parlementaire et à l’intérêt général.","effects":{"budget":2,"assemblee":-2},"news":"Budget prorogé : le chef du gouvernement vante la « continuité »"},{"tone":"offensive","label":"Si le budget attend, c’est parce que certains groupes préfèrent leurs intérêts à ceux du pays. Les électeurs sauront leur envoyer la facture.","effects":{"popularite":4,"assemblee":-4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Un allié « réfléchit » en répondant uniquement par écrit"}],"news":"Le chef du gouvernement menace d’envoyer la « facture » aux groupes"}]},{"id":"espagne-q-incendies-volontaires","theme":"crise","crisisId":"espagne-canicule-et-incendies","text":"Les pompiers luttent contre des feux dans trois régions par quarante-deux degrés. Que dites-vous aux familles évacuées et aux volontaires épuisés ?","answers":[{"tone":"franche","label":"Merci, et pardon : la prévention a manqué des moyens. Nous indemniserons vite, recruterons des brigades et nettoierons les forêts avant l’été prochain.","effects":{"popularite":4,"budget":-5},"delayed":[{"delay":3,"effects":{"ecologie":2},"label":"Les brigades forestières recrutent avant le prochain été"}],"news":"Incendies : le chef du gouvernement dit merci aux pompiers, et pardon"},{"tone":"langue-de-bois","label":"Toute notre solidarité va aux familles touchées. Les services de secours sont pleinement mobilisés et la coordination entre administrations est assurée.","effects":{"popularite":2,"securite":-2},"news":"Incendies : « toute notre solidarité » du chef du gouvernement"},{"tone":"offensive","label":"Ce n’est pas le moment des polémiques. Que ceux qui pointent du doigt viennent d’abord porter un seau, plutôt que des micros.","effects":{"securite":3,"popularite":2,"cohesion":-4},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les journalistes rangent leurs micros, mais pas leurs notes"}],"news":"Le chef du gouvernement : « Venez porter un seau, pas un micro »"}]},{"id":"espagne-q-championnat-ferie","theme":"crise","crisisId":"espagne-victoire-championnat","text":"L’équipe nationale a remporté le championnat et le pays chante dans les rues. Allez-vous décréter un jour férié, ou seulement une pause un peu prolongée ?","answers":[{"tone":"franche","label":"Je rêve d’un jour férié, mais l’économie ne le paierait pas. Nous ferons une réception, une parade, et un mercredi matin raisonnablement indulgent.","effects":{"popularite":4,"economie":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les employeurs découvrent le concept de « mercredi indulgent »"}],"news":"Le chef du gouvernement offre une parade et un « mercredi indulgent »"},{"tone":"langue-de-bois","label":"Cette victoire appartient à tous les Espagnols, et à toutes les générations qui ont cru à ce sport. Les modalités de célébration seront étudiées avec les fédérations.","effects":{"popularite":2,"economie":-2},"news":"Victoire : les « modalités de célébration » seront étudiées avec les fédérations"},{"tone":"offensive","label":"Un jour férié, bien sûr ! Un pays qui gagne a droit à se reposer. Les entreprises qui protestent n’aiment ni le sport ni la joie.","effects":{"popularite":6,"economie":-4,"budget":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Le comptable en chef sort sa calculatrice, puis sa chaise"}],"news":"Le chef du gouvernement décrète un jour férié, les entreprises soupirent"}]},{"id":"espagne-q-goutte-froide-alerte","theme":"crise","crisisId":"espagne-goutte-froide","text":"Des pluies diluviennes ont transformé des rues en rivières et des parkings en aquariums. L’alerte est-elle arrivée trop tard, ou la pluie trop vite ?","answers":[{"tone":"franche","label":"L’alerte est arrivée trop tard pour certains, et nous le devons à ceux qui ont tout perdu. Il y aura une enquête, des aides rapides et des systèmes d’alerte repensés.","effects":{"popularite":3,"budget":-5},"delayed":[{"delay":3,"effects":{"securite":2},"label":"Les sirènes sont testées avant la prochaine averse"}],"news":"Pluies : le chef du gouvernement promet enquête, aides et nouvelle alerte"},{"tone":"langue-de-bois","label":"Nos pensées vont aux victimes et à leurs proches. Les protocoles ont été appliqués, et leur évaluation sera menée avec toute la rigueur nécessaire.","effects":{"securite":2,"popularite":-2},"news":"Pluies : « les protocoles ont été appliqués », dit le chef du gouvernement"},{"tone":"offensive","label":"Ce n’est pas le moment de chercher des coupables, mais de reconstruire. J’invite chacun à se concentrer sur les secours plutôt que sur les caméras.","effects":{"securite":3,"cohesion":-4,"international":-2},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Les familles réclament pourtant des réponses précises"}],"news":"Le chef du gouvernement refuse de désigner des coupables après les pluies"}]},{"id":"espagne-q-tracteurs-cortes","theme":"crise","crisisId":"espagne-tracteurs-aux-cortes","text":"Des tracteurs bloquent l’accès aux Cortes, et leurs conducteurs dénoncent des normes, des prix et des paperasses. Écoutez-vous les agriculteurs avant que la moissonneuse n’arrive ?","answers":[{"tone":"franche","label":"Je les recevrai demain, ils ont raison sur la paperasse et sur les prix payés aux producteurs. Pas sur tout, mais assez pour mériter un rendez-vous.","effects":{"cohesion":4,"budget":-3},"delayed":[{"delay":2,"effects":{"economie":2},"label":"Les tracteurs repartent avec des formulaires plus courts"}],"news":"Le chef du gouvernement reçoit les agriculteurs, ils ont « raison sur la paperasse »"},{"tone":"langue-de-bois","label":"Nous entendons les préoccupations légitimes du monde agricole et poursuivons une concertation constructive avec ses représentants.","effects":{"cohesion":2,"economie":-2},"news":"Tracteurs : le chef du gouvernement entend « les préoccupations légitimes »"},{"tone":"offensive","label":"On ne gouverne pas sous la menace d’un moteur diesel. Qu’ils déplacent leurs tracteurs, puis nous parlerons, dans l’ordre et dans le calme.","effects":{"securite":3,"cohesion":-4,"popularite":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les tracteurs klaxonnent en do majeur"}],"news":"Le chef du gouvernement : « On ne gouverne pas sous la menace d’un moteur »"}]},{"id":"espagne-q-greve-pont","theme":"crise","text":"Une grève des transports tombe en plein pont, quand tout le monde veut partir. Négociez-vous avec les syndicats ou avec les embouteillages ?","answers":[{"tone":"franche","label":"Avec les deux, hélas. Je reçois les syndicats ce soir et je demande un service minimum, même si je sais que nous le paierons ensuite en concessions.","effects":{"economie":3,"budget":-3},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les trains repartent… avec des horaires qui font rêver"}],"news":"Le chef du gouvernement négocie avec les syndicats et les embouteillages"},{"tone":"langue-de-bois","label":"Le dialogue social reste notre méthode. Nous appelons chacun à la responsabilité afin de garantir la mobilité des usagers dans de bonnes conditions.","effects":{"economie":2,"popularite":-2},"news":"Grève : le chef du gouvernement appelle à « la responsabilité de chacun »"},{"tone":"offensive","label":"On ne prend pas un pays en otage pour un pont de trois jours. J’exigerai un service minimum, et la loi sera appliquée sans tendresse.","effects":{"economie":3,"popularite":2,"cohesion":-5},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les syndicats annoncent un nouveau pont… de grève"}],"news":"Le chef du gouvernement exige un service minimum, loi à l’appui"}]},{"id":"espagne-q-scandale-tuyaux","theme":"scandale","text":"Un ministre aurait attribué un contrat d’irrigation à l’entreprise de son beau-frère, spécialisée dans les tuyaux. Il assure que « c’est de famille ». Quelle sanction ?","answers":[{"tone":"franche","label":"Je lui ai demandé de suspendre le contrat et de coopérer à l’enquête. Si les faits sont avérés, il quittera le gouvernement sans délai ni cérémonie.","effects":{"popularite":4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Le ministre se découvre soudain un grand sens du devoir"}],"news":"Tuyaux : le chef du gouvernement suspend le contrat du beau-frère"},{"tone":"langue-de-bois","label":"Toute la lumière sera faite sur cette affaire, dans le respect de la présomption d’innocence et des procédures prévues pour ce type de situation.","effects":{"popularite":2,"assemblee":-2},"news":"Le chef du gouvernement promet « toute la lumière » sur les tuyaux"},{"tone":"offensive","label":"Cette affaire est un tuyau percé de l’opposition : elle a signé trois contrats semblables et n’a rien dit. Qu’elle commence par fermer son robinet.","effects":{"popularite":3,"assemblee":-3,"cohesion":-3},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Un journaliste retrouve les trois contrats, et les publie"}],"news":"Le chef du gouvernement accuse l’opposition d’avoir « signé trois contrats » semblables"}]},{"id":"espagne-q-scandale-fuite-poissons","theme":"scandale","text":"Un document confidentiel sur le plan hydrologique a fuité, annoté de dessins de poissons et de remarques peu flatteuses sur les présidents régionaux. Qui a laissé la porte du bureau ouverte ?","answers":[{"tone":"franche","label":"C’est une faute de mon équipe, donc de moi. Les annotations étaient maladroites et je présente mes excuses aux présidents régionaux, poissons compris.","effects":{"cohesion":3,"popularite":-3},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Les présidents acceptent les excuses, pas le dessin"}],"news":"Fuite : le chef du gouvernement s’excuse auprès des présidents, et des poissons"},{"tone":"langue-de-bois","label":"Une enquête interne a été ouverte afin d’établir les circonstances de cette fuite et d’en tirer toutes les conséquences utiles.","effects":{"popularite":2,"cohesion":-2},"news":"Fuite : le chef du gouvernement ouvre une « enquête interne »"},{"tone":"offensive","label":"Ce qui m’intéresse, c’est le contenu du plan, pas les dessins. Celui qui a fuité a préféré les poissons à l’eau, et c’est regrettable pour tous.","effects":{"economie":3,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":3,"effects":{"assemblee":-3},"label":"Un président régional publie son propre dessin de poisson"}],"news":"Le chef du gouvernement : le plan compte, « pas les poissons »"}]},{"id":"espagne-q-scandale-villa-seminaire","theme":"scandale","text":"Un conseiller aurait réservé sa villa de vacances à l’État pour y tenir un « séminaire de réflexion » de dix jours, piscine incluse. Remboursera-t-il, ou facturera-t-il la réflexion ?","answers":[{"tone":"franche","label":"Il remboursera chaque euro, et la réflexion s’arrête là. J’ai demandé un code de conduite : les séminaires se tiendront dans des salles sans piscine.","effects":{"popularite":4,"budget":2,"assemblee":-3},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les séminaires se tiennent désormais dans des salles climatisées"}],"news":"Villa : le conseiller rembourse, les séminaires perdent leur piscine"},{"tone":"langue-de-bois","label":"Les règles de passation et de remboursement seront réexaminées avec rigueur, conformément aux principes de transparence qui nous guident.","effects":{"popularite":2,"budget":-2},"news":"Villa : le chef du gouvernement invoque la « transparence »"},{"tone":"offensive","label":"La réflexion est un travail, et un travail mérite un cadre. Ceux qui dénoncent la piscine n’ont jamais pensé à plus de trois mètres de profondeur.","effects":{"assemblee":3,"popularite":-4,"budget":-2},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"Un sondage évalue la profondeur de la réflexion"}],"news":"Le chef du gouvernement défend la « réflexion en piscine »"}]},{"id":"espagne-q-conseil-sieste","theme":"popularite","text":"Le pays déjeune à quinze heures et dîne à vingt-deux : avez-vous déjà tenu un conseil des ministres pendant la sieste, et les décisions étaient-elles meilleures ?","answers":[{"tone":"franche","label":"Une fois, et le dossier du budget a été adopté sans un mot, comme si tout le monde dormait déjà. Depuis, mes ministres demandent des réunions plus courtes.","effects":{"popularite":3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les Espagnols apprécient l’aveu, surtout après déjeuner"}],"news":"Le chef du gouvernement avoue un conseil des ministres « un peu somnolent »"},{"tone":"langue-de-bois","label":"Le rythme de nos travaux est adapté à nos traditions et aux exigences de l’action publique, dans un esprit d’efficacité partagée.","effects":{"popularite":2,"economie":-2},"news":"Le chef du gouvernement défend le « rythme adapté » du conseil"},{"tone":"offensive","label":"Les meilleures décisions du pays ont été prises après un bon repas. Ceux qui travaillent le ventre vide sont à l’origine des pires lois d’Europe.","effects":{"popularite":5,"international":-3,"economie":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Un voisin européen envoie un menu de travail, avec ironie"}],"news":"Le chef du gouvernement : « Les meilleures lois naissent après un repas »"}]},{"id":"espagne-q-derby-tribune","theme":"cohesion","text":"Le grand derby de la capitale divise deux moitiés du pays, et le président d’un club vous a invité en tribune. Quel maillot portez-vous pour garder la paix civile ?","answers":[{"tone":"franche","label":"Celui de l’arbitre, et avec un sifflet que personne ne m’a prêté. Je déteste perdre, mais je déteste encore plus que le pays se dispute pour un ballon.","effects":{"cohesion":4,"popularite":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les deux tribunes rient, ce qui est déjà un exploit"}],"news":"Le chef du gouvernement ira au derby « en arbitre »"},{"tone":"langue-de-bois","label":"Le sport rassemble les générations et les territoires. Je serai présent en tant que spectateur attentif aux valeurs de respect et de fair-play.","effects":{"cohesion":2,"popularite":-2},"news":"Derby : le chef du gouvernement invoque « respect et fair-play »"},{"tone":"offensive","label":"Le maillot du club qui a gagné le plus de trophées ! Que l’autre camp vienne se plaindre, la rivalité, ça se mérite.","effects":{"popularite":5,"cohesion":-5},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"La moitié du pays brûle une écharpe en effigie"}],"news":"Le chef du gouvernement choisit un maillot, et un camp avec"}]},{"id":"espagne-q-tortilla-oignon","theme":"cohesion","text":"Question grave, chef du gouvernement : la tortilla de pommes de terre, avec ou sans oignon ? Le pays s’empoigne depuis des générations, et vous êtes attendu.","answers":[{"tone":"franche","label":"Avec, et je vous l’assure en toute franchise, même si je perds des amis. Une tortilla sans oignon est une promesse sans budget.","effects":{"popularite":4,"cohesion":-3},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les partisans sans oignon sortent les poêles"}],"news":"Le chef du gouvernement choisit : tortilla avec oignon"},{"tone":"langue-de-bois","label":"La tortilla est un patrimoine culinaire qui appartient à tous les Espagnols, avec ou sans oignon, dans le respect des traditions familiales de chacun.","effects":{"cohesion":2,"popularite":-2},"news":"Tortilla : le chef du gouvernement refuse de trancher, par patrimoine"},{"tone":"offensive","label":"Cette question divise pour mieux régner ; je refuse ce piège. Le vrai débat est de savoir qui paie les œufs, et je vous invite à le trancher ensemble.","effects":{"economie":3,"popularite":-2,"cohesion":-3},"delayed":[{"delay":3,"effects":{"pouvoirAchat":-2},"label":"Les œufs montent en bourse, les oignons en tribune"}],"news":"Tortilla : le chef du gouvernement répond par « qui paie les œufs »"}]},{"id":"espagne-q-fetes-patronales","theme":"popularite","text":"Les élections doivent éviter les fêtes patronales de plusieurs milliers de communes, soit à peu près tous les week-ends. Avez-vous déjà dansé avec une fanfare pour gagner une voix ?","answers":[{"tone":"franche","label":"Oui, et j’ai perdu un soulier. Je n’en tire aucune fierté électorale, seulement un grand respect pour les fanfares, qui ne s’arrêtent jamais.","effects":{"popularite":4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les fanfares offrent au chef du gouvernement une paire neuve"}],"news":"Le chef du gouvernement avoue avoir dansé avec une fanfare… et perdu un soulier"},{"tone":"langue-de-bois","label":"Les fêtes locales sont un moment de convivialité et d’échange avec les citoyens, qui font partie de notre vie démocratique.","effects":{"popularite":2,"cohesion":-2},"news":"Fêtes patronales : le chef du gouvernement salue la « convivialité »"},{"tone":"offensive","label":"Je danse mieux que mon adversaire, qui compte les pas comme il compte les chiffres. Les fanfares me connaissent, elles ne le connaissent pas.","effects":{"popularite":5,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Le rival répond avec une vidéo de flamenco, très applaudie"}],"news":"Le chef du gouvernement se déclare meilleur danseur que son rival"}]},{"id":"espagne-q-langues-cooficielles","theme":"cohesion","text":"Dans l’hémicycle, on parle désormais plusieurs langues, avec un casque de traduction pour chacun. Les langues cooficielles sont-elles un trésor ou un casse-tête ?","answers":[{"tone":"franche","label":"Les deux, et je ne m’en plains pas. C’est un trésor qui coûte des casques, et je préfère payer des casques que perdre une langue.","effects":{"cohesion":4,"budget":-3},"delayed":[{"delay":3,"effects":{"assemblee":2},"label":"Les interprètes réclament une prime de patience"}],"news":"Le chef du gouvernement : « un trésor qui coûte des casques »"},{"tone":"langue-de-bois","label":"La pluralité linguistique est une richesse constitutionnelle que nous entendons préserver dans toutes ses dimensions et pour tous les citoyens.","effects":{"cohesion":2,"popularite":-2},"news":"Langues : le chef du gouvernement évoque une « richesse constitutionnelle »"},{"tone":"offensive","label":"Les casques coûtent moins cher que les querelles. Que ceux qui se plaignent du bruit essaient d’écouter, c’est un sport formateur.","effects":{"popularite":3,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Un groupe commande des casques supplémentaires, par principe"}],"news":"Le chef du gouvernement : écouter est « un sport formateur »"}]},{"id":"espagne-q-sommet-quinze-aout","theme":"international","text":"L’Espagne est candidate à l’organisation d’un grand sommet international. Où allez-vous loger les délégations en plein mois d’août, quand toutes les chambres sont prises par des vacanciers ?","answers":[{"tone":"franche","label":"Dans des hôtels en dehors du littoral, et nous ferons le sommet en septembre. Je préfère renoncer à août que d’organiser une réunion sans lits ni oxygène.","effects":{"international":3,"economie":-2},"delayed":[{"delay":3,"effects":{"international":2},"label":"Les délégations arrivent reposées, et presque à l’heure"}],"news":"Le chef du gouvernement reporte le sommet « pour trouver des lits »"},{"tone":"langue-de-bois","label":"Nous disposons d’infrastructures d’accueil de premier ordre et d’une longue expérience dans l’organisation d’événements d’envergure internationale.","effects":{"international":2,"popularite":-2},"news":"Sommet : le chef du gouvernement vante des « infrastructures de premier ordre »"},{"tone":"offensive","label":"Si le sommet est trop exigeant pour d’autres capitales, il sera chez nous : même à quarante degrés, notre hospitalité tient en terrasse.","effects":{"popularite":4,"international":-3,"economie":2},"delayed":[{"delay":2,"effects":{"international":-3},"label":"Des délégations réclament des ventilateurs diplomatiques"}],"news":"Le chef du gouvernement : l’hospitalité espagnole « tient en terrasse »"}]},{"id":"espagne-q-anglais-sommet","theme":"international","text":"Lors des sommets internationaux, votre anglais est célèbre pour son accent et sa créativité grammaticale. Un interprète est-il un luxe ou une nécessité diplomatique ?","answers":[{"tone":"franche","label":"Une nécessité, et mon accent est un patrimoine que je ne vendrai pas. Je préfère parler clairement dans ma langue que mal dans la vôtre.","effects":{"international":3,"popularite":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"L’accent devient un hashtag, puis un souvenir attendri"}],"news":"Le chef du gouvernement garde l’interprète, et l’accent"},{"tone":"langue-de-bois","label":"Chaque langue est un pont, et nous utilisons ceux qui conviennent le mieux à chaque rencontre, dans un esprit de compréhension et de respect mutuel.","effects":{"international":2,"popularite":-2},"news":"Le chef du gouvernement compare chaque langue à « un pont »"},{"tone":"offensive","label":"Mon anglais est parfait pour dire non avec élégance. Ceux qui se moquent de mon accent n’ont jamais négocié un budget en espagnol à deux heures du matin.","effects":{"popularite":4,"international":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Un homologue offre des cours en ligne, avec un sourire"}],"news":"Le chef du gouvernement : mon anglais est « parfait pour dire non »"}]}]}'),u={pays:e,version:1,textes:s,institutions:n,election:t,lois:a,crises:o,missions:i,presse:r};export{o as crises,u as default,t as election,n as institutions,a as lois,i as missions,e as pays,r as presse,s as textes,l as version};
